#include <iostream>
#include <vector>

int main() {
    std::vector<int> memory(100, 0);

    // Nạp chương trình SML Ví dụ 1: Đọc A, B, tính A + B và in C
    memory[0] = 1007; // READ -> memory[07]
    memory[1] = 1008; // READ -> memory[08]
    memory[2] = 2007; // LOAD memory[07] vào accumulator
    memory[3] = 3008; // ADD memory[08] vào accumulator
    memory[4] = 2109; // STORE accumulator vào memory[09]
    memory[5] = 1109; // WRITE memory[09] ra màn hình
    memory[6] = 4300; // HALT

    int accumulator = 0;
    int instructionCounter = 0;
    int instructionRegister = 0;
    int operationCode = 0;
    int operand = 0;
    bool running = true;

    while (running && instructionCounter < 100) {
        // 1. Fetch
        instructionRegister = memory[instructionCounter];
        // 2. Decode
        operationCode = instructionRegister / 100;
        operand = instructionRegister % 100;

        // 3. Execute
        switch (operationCode) {
            case 10: // READ
                std::cin >> memory[operand];
                break;
            case 11: // WRITE
                std::cout << "Sum: " << memory[operand] << "\n";
                break;
            case 20: // LOAD
                accumulator = memory[operand];
                break;
            case 21: // STORE
                memory[operand] = accumulator;
                break;
            case 30: // ADD
                accumulator += memory[operand];
                break;
            case 43: // HALT
                running = false;
                break;
            default:
                running = false;
                break;
        }

        if (running) {
            ++instructionCounter;
        }
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <iomanip>

constexpr int SML_READ       = 10;
constexpr int SML_WRITE      = 11;
constexpr int SML_LOAD       = 20;
constexpr int SML_STORE      = 21;
constexpr int SML_ADD        = 30;
constexpr int SML_SUBTRACT   = 31;
constexpr int SML_DIVIDE     = 32;
constexpr int SML_MULTIPLY   = 33;
constexpr int SML_BRANCH     = 40;
constexpr int SML_BRANCHNEG  = 41;
constexpr int SML_BRANCHZERO = 42;
constexpr int SML_HALT       = 43;
constexpr int SENTINEL       = -99999;

void dump(int accumulator, int instructionCounter, int instructionRegister,
          int operationCode, int operand, const std::vector<int>& memory) {
    std::cout << "\nREGISTERS:\n";
    std::cout << "accumulator          " << std::showpos << std::internal
              << std::setw(5) << std::setfill('0') << accumulator << std::noshowpos << "\n";
    std::cout << "instructionCounter      " << std::setw(2) << std::setfill('0') << instructionCounter << "\n";
    std::cout << "instructionRegister  " << std::showpos << std::internal
              << std::setw(5) << std::setfill('0') << instructionRegister << std::noshowpos << "\n";
    std::cout << "operationCode           " << std::setw(2) << std::setfill('0') << operationCode << "\n";
    std::cout << "operand                 " << std::setw(2) << std::setfill('0') << operand << "\n";

    std::cout << "\nMEMORY:\n  ";
    for (int col = 0; col < 10; ++col) {
        std::cout << std::setw(6) << std::setfill(' ') << col;
    }
    std::cout << "\n";

    for (int row = 0; row < 100; row += 10) {
        std::cout << std::setw(2) << std::setfill(' ') << row << " ";
        for (int col = 0; col < 10; ++col) {
            std::cout << std::showpos << std::internal << std::setw(5) << std::setfill('0')
                      << memory[row + col] << std::noshowpos << " ";
        }
        std::cout << "\n";
    }
}

void load(std::vector<int>& memory) {
    int address = 0;
    int word = 0;
    while (address < 100 && (std::cin >> word)) {
        if (word == SENTINEL) {
            break;
        }
        if (word >= -9999 && word <= 9999) {
            memory[address++] = word;
        }
    }
}

void simulate(std::vector<int>& memory, int* acc, int* ic, int* ir, int* opCode, int* opnd) {
    bool running = true;
    int steps = 0;
    while (running) {
        if (*ic < 0 || *ic >= 100) { std::cout << "*** Invalid instruction address ***\n"; break; }
        if (++steps > 10000) { std::cout << "*** Step limit exceeded ***\n"; break; }
        *ir = memory[*ic];
        if (*ir < 0) { std::cout << "*** Invalid operation code ***\n"; break; }
        *opCode = *ir / 100;
        *opnd = *ir % 100;

        bool branched = false;

        switch (*opCode) {
            case SML_READ:
                int word;
                if (!(std::cin >> word) || word < -9999 || word > 9999) {
                    std::cout << "*** Invalid input word ***\n"; running = false;
                } else { memory[*opnd] = word; }
                break;
            case SML_WRITE:
                std::cout << "OUTPUT: " << memory[*opnd] << "\n";
                break;
            case SML_LOAD:
                *acc = memory[*opnd];
                break;
            case SML_STORE:
                memory[*opnd] = *acc;
                break;
            case SML_ADD:
                *acc += memory[*opnd];
                if (*acc < -9999 || *acc > 9999) {
                    std::cout << "*** Accumulator overflow ***\n";
                    std::cout << "*** Simpletron execution abnormally terminated ***\n";
                    running = false;
                }
                break;
            case SML_SUBTRACT:
                *acc -= memory[*opnd];
                if (*acc < -9999 || *acc > 9999) { std::cout << "*** Accumulator overflow ***\n"; running = false; }
                break;
            case SML_DIVIDE:
                if (memory[*opnd] == 0) {
                    std::cout << "*** Attempt to divide by zero ***\n";
                    std::cout << "*** Simpletron execution abnormally terminated ***\n";
                    running = false;
                } else {
                    *acc /= memory[*opnd];
                }
                break;
            case SML_MULTIPLY:
                *acc *= memory[*opnd];
                if (*acc < -9999 || *acc > 9999) { std::cout << "*** Accumulator overflow ***\n"; running = false; }
                break;
            case SML_BRANCH:
                *ic = *opnd;
                branched = true;
                break;
            case SML_BRANCHNEG:
                if (*acc < 0) {
                    *ic = *opnd;
                    branched = true;
                }
                break;
            case SML_BRANCHZERO:
                if (*acc == 0) {
                    *ic = *opnd;
                    branched = true;
                }
                break;
            case SML_HALT:
                std::cout << "*** Simpletron execution terminated ***\n";
                running = false;
                break;
            default:
                std::cout << "*** Invalid operation code ***\n";
                std::cout << "*** Simpletron execution abnormally terminated ***\n";
                running = false;
                break;
        }

        if (!branched && running) {
            ++(*ic);
        }
    }
}

int main() {
    std::vector<int> memory(100, 0);
    int accumulator = 0;
    int instructionCounter = 0;
    int instructionRegister = 0;
    int operationCode = 0;
    int operand = 0;

    load(memory);
    simulate(memory, &accumulator, &instructionCounter, &instructionRegister, &operationCode, &operand);
    dump(accumulator, instructionCounter, instructionRegister, operationCode, operand, memory);

    return 0;
}
